    if isMastered {
        let masteredAt = Date()
        terms[index].isMastered = true
        terms[index].dateMastered = masteredAt
        LearningActivityStore.shared.recordWordMastered()
    } else {
        // Read the earned-on date before clearing it, and hand the
        // milestone back to that day rather than to today.
        let earnedOn = terms[index].dateMastered
        terms[index].isMastered = false
        terms[index].dateMastered = nil
        if let earnedOn {
            LearningActivityStore.shared.undoWordMastered(on: earnedOn)
        }
    }
}

