// MARK: - Full-width Adaptive Contribution Heatmap

struct ContributionHeatmap: View {
    let activities: [DailyActivity]
    @Binding var selectedDate: DailyActivity?
    var isCompact: Bool = false
    let colorForScore: (Int) -> Color

    private var spacing: CGFloat { isCompact ? 2 : 3 }
    private let rows: Int = 7 // Days of week
    private var labelWidth: CGFloat { isCompact ? 16 : 20 }
    private var monthLabelHeight: CGFloat { isCompact ? 14 : 16 }

    /// Empty slots before the first activity so each row is a true calendar
    /// weekday (GitHub-style). The gutter labels put Sunday at row 0 and
    /// M/W/F at rows 1/3/5, so the first date is offset by `weekday − 1`
    /// (`Calendar.weekday`: 1 = Sunday … 7 = Saturday). Without this padding
    /// the grid just wrapped every 7 cells from an arbitrary start day and
    /// the M/W/F labels lied.
    private var leadingEmptyDays: Int {
        guard let first = activities.first else { return 0 }
        return Calendar.current.component(.weekday, from: first.date) - 1
    }

    /// Gutter labels for the seven weekday rows, index 0 = Sunday to match
    /// `leadingEmptyDays`. Only the alternating rows are labeled so the
    /// initials do not crowd the grid — that is the M/W/F pattern the English
    /// build has always drawn. The symbols come from the *app* language rather
    /// than a hard-coded English array, which otherwise printed M/W/F even in
    /// the 中文 interface (where they should read 一/三/五).
    private var weekdayInitials: [String] {
        let formatter = DateFormatter()
        formatter.locale = LocalizationManager.shared.locale
        guard let symbols = formatter.veryShortWeekdaySymbols, symbols.count == 7 else {
            return ["", "M", "", "W", "", "F", ""]
        }
        return (0..<7).map { $0 % 2 == 1 ? symbols[$0] : "" }
    }

    var body: some View {
        GeometryReader { geometry in
            let availableWidth = geometry.size.width - (isCompact ? 24 : 32) - labelWidth
            let weeks = Int(ceil(Double(activities.count + leadingEmptyDays) / 7.0))

            // Calculate cell size to fit all weeks in available width
            let totalSpacing = CGFloat(weeks - 1) * spacing
            let minCellSize: CGFloat = isCompact ? 6 : 8
            let maxCellSize: CGFloat = isCompact ? 10 : 14
            let cellSize = max(minCellSize, min(maxCellSize, (availableWidth - totalSpacing) / CGFloat(weeks)))
            let totalHeight = CGFloat(rows) * cellSize + CGFloat(rows - 1) * spacing

            VStack(alignment: .leading, spacing: isCompact ? 2 : 4) {
                HStack(alignment: .top, spacing: isCompact ? 2 : 4) {
                    // Day labels - show fewer on compact
                    VStack(alignment: .trailing, spacing: spacing) {
                        ForEach(Array(weekdayInitials.enumerated()), id: \.offset) { _, day in
                            Text(day)
                                .font(.system(size: isCompact ? 7 : 9, weight: .medium))
                                .foregroundStyle(.secondary)
                                .frame(width: labelWidth, height: cellSize)
                        }
                    }

                    // Weeks grid - fills available width
                    HStack(alignment: .top, spacing: spacing) {
                        ForEach(0..<weeks, id: \.self) { week in
                            VStack(spacing: spacing) {
                                ForEach(0..<rows, id: \.self) { dayOfWeek in
                                    // Shift by the leading pad so row == real weekday.
                                    let index = week * 7 + dayOfWeek - leadingEmptyDays
                                    if index >= 0 && index < activities.count {
                                        ContributionCell(
                                            activity: activities[index],
                                            size: cellSize,
                                            isSelected: selectedDate?.dateKey == activities[index].dateKey,
                                            colorForScore: colorForScore,
                                            onTap: {
                                                withAnimation(.smooth(duration: 0.2)) {
                                                    if selectedDate?.dateKey == activities[index].dateKey {
                                                        selectedDate = nil
                                                    } else {
                                                        selectedDate = activities[index]
                                                    }
                                                }
                                            }
                                        )
                                    } else if index < 0 {
                                        // Pad slot before the range begins: keep the
                                        // column height without drawing a fake day.
                                        Color.clear
                                            .frame(width: cellSize, height: cellSize)
                                    } else {
                                        RoundedRectangle(cornerRadius: isCompact ? 1 : 2)
                                            .fill(Color.gray.opacity(0.15))
                                            .frame(width: cellSize, height: cellSize)
                                    }
                                }
                            }
                        }
                    }
                }

                // Month labels row
                HStack(spacing: 0) {
                    // Spacer for day label column
                    Spacer()
                        .frame(width: labelWidth + (isCompact ? 2 : 4))

                    // Month labels positioned under their respective weeks
                    monthLabelsView(weeks: weeks, cellSize: cellSize)
                }
            }
            .padding(.horizontal, isCompact ? 8 : 16)
            .frame(height: totalHeight + monthLabelHeight + 4)
        }
        .frame(height: calculateHeight())
    }

    @ViewBuilder
    private func monthLabelsView(weeks: Int, cellSize: CGFloat) -> some View {
        let monthPositions = calculateMonthPositions(weeks: weeks, cellSize: cellSize)

        ZStack(alignment: .leading) {
            ForEach(monthPositions, id: \.month) { monthInfo in
                Text(monthInfo.label)
                    .font(.system(size: isCompact ? 7 : 9, weight: .medium))
                    .foregroundStyle(.secondary)
                    .offset(x: monthInfo.xOffset)
            }
        }
        .frame(height: monthLabelHeight)
        .frame(maxWidth: .infinity, alignment: .leading)
    }

    private struct MonthPosition: Hashable {
        let month: Int
        let year: Int
        let label: String
        let xOffset: CGFloat

        func hash(into hasher: inout Hasher) {
            hasher.combine(month)
            hasher.combine(year)
        }

        static func == (lhs: MonthPosition, rhs: MonthPosition) -> Bool {
            lhs.month == rhs.month && lhs.year == rhs.year
        }
    }

    private func calculateMonthPositions(weeks: Int, cellSize: CGFloat) -> [MonthPosition] {
        guard !activities.isEmpty else { return [] }

        let calendar = Calendar.current
        let monthFormatter = DateFormatter()
        // Without an explicit locale the abbreviations follow the *device*
        // language, so the strip stayed English for a 中文 interface (and could
        // even show 月份 names to an English user on a Chinese device). Pin it
        // to the in-app language instead.
        monthFormatter.locale = LocalizationManager.shared.locale
        monthFormatter.dateFormat = "MMM"

        var positions: [MonthPosition] = []
        var lastMonth: Int = -1
        var lastYear: Int = -1

        for week in 0..<weeks {
            // Check the first day of each week (the top row), accounting for
            // the leading weekday-alignment pad; week 0 may start mid-column,
            // so clamp to the first real day.
            let index = max(0, week * 7 - leadingEmptyDays)
            guard index < activities.count else { continue }

            let date = activities[index].date
            let month = calendar.component(.month, from: date)
            let year = calendar.component(.year, from: date)

            // If this is a new month, record its position
            if month != lastMonth || year != lastYear {
                let xOffset = CGFloat(week) * (cellSize + spacing)
                positions.append(MonthPosition(
                    month: month,
                    year: year,
                    label: monthFormatter.string(from: date),
                    xOffset: xOffset
                ))
                lastMonth = month
                lastYear = year
            }
        }

        return positions
    }

    private func calculateHeight() -> CGFloat {
        // Estimate height based on typical cell size (smaller for compact mode)
        let estimatedCellSize: CGFloat = isCompact ? 8 : 11
        let estimatedSpacing: CGFloat = isCompact ? 2 : 3
        return CGFloat(rows) * estimatedCellSize + CGFloat(rows - 1) * estimatedSpacing + monthLabelHeight + (isCompact ? 8 : 12)
    }
}

struct ContributionCell: View {
    let activity: DailyActivity
    let size: CGFloat
    let isSelected: Bool
    let colorForScore: (Int) -> Color
    let onTap: () -> Void

    var body: some View {
        RoundedRectangle(cornerRadius: max(2, size * 0.15))
            .fill(colorForActivity)
            .frame(width: size, height: size)
            .overlay {
                if isSelected {
                    RoundedRectangle(cornerRadius: max(2, size * 0.15))
                        .strokeBorder(.tint, lineWidth: 2)
                }
            }
            .scaleEffect(isSelected ? 1.15 : 1.0)
            .onTapGesture(perform: onTap)
            // "March 3: 12 activities" — the Date interpolation resolves via
            // the environment locale, so VoiceOver reads the app language.
            .accessibilityLabel(Text("\(activity.date, format: .dateTime.month(.wide).day()): \(activity.activityScore) activities"))
            .accessibilityAddTraits(.isButton)
    }

    private var colorForActivity: Color {
        colorForScore(activity.activityScore)
    }
}

// MARK: - MasteryLevel Extensions

extension MasteryLevel {
    var sortOrder: Int {
        switch self {
        case .new: return 0
        case .learning: return 1
        case .familiar: return 2
        case .proficient: return 3
        case .mastered: return 4
        }
    }

    /// Wrapped in `String(localized:)` because this is a plain `String` handed
    /// to callers verbatim — as a bare literal it bypassed the string catalog
    /// and stayed English in the 中文 interface. The keys match
    /// `MasteryLevel.label`, so both properties share one catalog entry.
    var displayName: String {
        switch self {
        case .new: return String(localized: "New", bundle: .appLanguage)
        case .learning: return String(localized: "Learning", bundle: .appLanguage)
        case .familiar: return String(localized: "Familiar", bundle: .appLanguage)
        case .proficient: return String(localized: "Proficient", bundle: .appLanguage)
        case .mastered: return String(localized: "Mastered", bundle: .appLanguage)
        }
    }
}

