            }
            .buttonStyle(.plain)
            .foregroundStyle(barChartTimeRange == range ? .primary : .secondary)
            .background {
                if barChartTimeRange == range {
                    Capsule()
                        .fill(.tint.opacity(0.15))
                        .matchedGeometryEffect(id: "barChartRange", in: namespace)
                }
            }
        }
    }
    .glassEffectCapsuleCompat()
}

