//
//  StatsView.swift
//  SwiftMandarin
//
//  Created by Claude on 2025.
//

import SwiftUI
import Charts

/// Main analytics dashboard view showing learning progress and activity
/// Features GitHub-style contribution chart and stacked bar charts
/// Adapts layout for iPhone, iPad, and macOS platforms
struct StatsView: View {
    @Environment(LearningActivityStore.self) private var activityStore
    @Environment(LearningProgressStore.self) private var progressStore
    @Environment(SavedTermsStore.self) private var termsStore

    @State private var barChartTimeRange: BarChartTimeRange = .week
    @State private var selectedContributionDate: DailyActivity?
    @State private var selectedMasterySegment: VocabularyMasterySegment?
    @State private var selectedPOSSegment: String?
    @Namespace private var namespace

    enum BarChartTimeRange: String, CaseIterable {
        case week = "7 Days"
        case twoWeeks = "14 Days"
        case month = "30 Days"

        var days: Int {
            switch self {
            case .week: return 7
            case .twoWeeks: return 14
            case .month: return 30
            }
        }

        /// The raw values are the stable case identity, so the range toggle
        /// renders this key instead. Drawing `rawValue` left the picker in
        /// English even when the interface language is 中文. Each case spells
        /// its key out as a literal because the catalog extractor cannot
        /// follow `rawValue`.
        var titleKey: LocalizedStringKey {
            switch self {
            case .week: return "7 Days"
            case .twoWeeks: return "14 Days"
            case .month: return "30 Days"
            }
        }

        /// How many days apart the x-axis labels sit. 30 individually labelled
        /// days collapse into an unreadable smear even on a Mac window, so the
        /// month range labels every third day; the shorter ranges still label
        /// every one.
        var axisLabelStride: Int {
            switch self {
            case .week, .twoWeeks: return 1
            case .month: return 3
            }
        }

        /// Weekday initials only stay unambiguous over a single week; longer
        /// ranges repeat every weekday, so they switch to day-of-month numbers.
        var usesWeekdayAxisLabels: Bool {
            self == .week
        }
    }

    enum VocabularyMasterySegment: String, CaseIterable {
        case learning = "Learning"
        case mastered = "Mastered"

        /// The raw values are the donut chart's foreground-style-scale domain
        /// and must keep matching it, so the center label and the legend read
        /// this key instead of `rawValue` to follow the interface language.
        var titleKey: LocalizedStringKey {
            switch self {
            case .learning: return "Learning"
            case .mastered: return "Mastered"
            }
        }
    }

    /// Platform detection for adaptive layouts
    private var isCompactWidth: Bool {
        #if os(iOS)
        return UIDevice.current.userInterfaceIdiom == .phone
        #else
        return false
        #endif
    }

    private var isIPad: Bool {
        #if os(iOS)
        return UIDevice.current.userInterfaceIdiom == .pad
        #else
        return false
        #endif
    }

